package com.railrush.game

import android.app.Activity
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.graphics.Color
import android.graphics.Typeface
import android.graphics.drawable.GradientDrawable
import android.opengl.GLSurfaceView
import android.view.*
import android.widget.*
import android.media.*
import org.json.JSONObject
import org.json.JSONArray
import kotlin.math.*

class MainActivity:Activity() {
    private lateinit var engine:Engine;private lateinit var renderer:RailRenderer;private lateinit var surface:GLSurfaceView
    private lateinit var root:FrameLayout;private lateinit var hud:LinearLayout;private lateinit var stats:TextView;private lateinit var powers:TextView;private lateinit var boardButton:Button;private lateinit var meters:PowerMeters
    private var panel:LinearLayout?=null;private var screen="";private var lastMode=Mode.MENU;private val handler=Handler(Looper.getMainLooper());private var lastHUD=0L;private var lastLog=0L
    private lateinit var sound:GameAudio;private lateinit var save:Save
    private var downX=0f;private var downY=0f;private var tapAt=0L;private var destroyed=false
    override fun onCreate(state:Bundle?){super.onCreate(state);window.addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(android.os.Build.VERSION.SDK_INT>=30){window.setDecorFitsSystemWindows(false);window.decorView.post{window.insetsController?.let{it.hide(WindowInsets.Type.systemBars());it.systemBarsBehavior=WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE}}};save=Save();engine=loadEngine();engine.boards=save.boards;sound=GameAudio();renderer=RailRenderer(this,engine);renderer.skin=save.skin
        root=FrameLayout(this);surface=GLSurfaceView(this);surface.setEGLContextClientVersion(2);surface.preserveEGLContextOnPause=true;surface.setRenderer(renderer);root.addView(surface)
        if(android.os.Build.MODEL.contains("sdk",true)||android.os.Build.FINGERPRINT.contains("generic",true))surface.addOnLayoutChangeListener{v,_,_,_,_,_,_,_,_->if(v.width>0&&v.height>0)surface.holder.setFixedSize((v.width*.6f).toInt(),(v.height*.6f).toInt())}
        root.setOnApplyWindowInsetsListener{v,i->if(android.os.Build.VERSION.SDK_INT>=30){val bars=i.getInsets(WindowInsets.Type.systemBars() or WindowInsets.Type.displayCutout());v.setPadding(bars.left,bars.top,bars.right,bars.bottom)}else{@Suppress("DEPRECATION") v.setPadding(i.systemWindowInsetLeft,i.systemWindowInsetTop,i.systemWindowInsetRight,i.systemWindowInsetBottom)};i};setContentView(root)
        hud=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(16),dp(12),dp(16),0)};root.addView(hud,FrameLayout.LayoutParams(-1,-2,Gravity.TOP))
        val top=LinearLayout(this);top.gravity=Gravity.TOP;top.addView(button("Ⅱ"){engine.pause();sound.pause();syncUI(true)},LinearLayout.LayoutParams(dp(46),dp(46)));top.addView(View(this),LinearLayout.LayoutParams(0,1,1f));stats=label("",22,Color.WHITE).apply{typeface=Typeface.create("sans-serif-black",Typeface.BOLD);gravity=Gravity.RIGHT;setShadowLayer(3f,1f,2f,Color.rgb(51,52,52));background=background(Color.argb(75,28,46,28),12);setPadding(dp(8),0,dp(8),0)};top.addView(stats,LinearLayout.LayoutParams(-2,-2));hud.addView(top)
        powers=label("",20,Color.WHITE);powers.typeface=Typeface.DEFAULT_BOLD;powers.setShadowLayer(3f,0f,2f,Color.DKGRAY);hud.addView(powers)
        meters=PowerMeters(this);root.addView(meters,FrameLayout.LayoutParams(-1,dp(135),Gravity.BOTTOM))
        boardButton=button("BOARD · ${save.boards}"){synchronized(engine){engine.board();save.boards=engine.boards;save.store()}};val bp=FrameLayout.LayoutParams(dp(106),dp(38),Gravity.BOTTOM or Gravity.LEFT);bp.bottomMargin=dp(138);bp.leftMargin=dp(10);root.addView(boardButton,bp)
        surface.setOnTouchListener{_,ev->when(ev.action){MotionEvent.ACTION_DOWN->{downX=ev.x;downY=ev.y;true};MotionEvent.ACTION_UP->{val dx=ev.x-downX;val dy=ev.y-downY;synchronized(engine){if(max(abs(dx),abs(dy))>dp(24)){if(abs(dx)>abs(dy))engine.move(if(dx>0)1 else -1)else if(dy<0)engine.jump()else engine.down()}else{val now=System.currentTimeMillis();if(now-tapAt<280){engine.board();save.boards=engine.boards;save.store();tapAt=0}else tapAt=now}};true};else->true}}
        engine.onEvent={name->renderer.emit(name);sound.effect(name);if(name=="crash")surface.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);if(name=="coin")surface.performHapticFeedback(HapticFeedbackConstants.CLOCK_TICK)}
        renderer.onFrame={val now=System.currentTimeMillis();if(now-lastHUD>80){lastHUD=now;handler.post{if(!destroyed)syncUI()}}};syncUI(true)
        if(intent.getBooleanExtra("autostart",false))startRun()
    }
    private fun loadEngine():Engine {val t=Tuning.fromJson(assets.open("config/gameplay.json").bufferedReader().use{it.readText()});val a=JSONObject(assets.open("config/route.json").bufferedReader().use{it.readText()}).getJSONArray("entities");val ts=ArrayList<Template>();for(i in 0 until a.length()){val p=a.getJSONObject(i);ts.add(Template(p.getString("id"),p.getString("kind"),p.getInt("lane"),p.getDouble("z"),p.getDouble("y"),p.getDouble("length")))};return Engine(t,ts.sortedBy{it.z})}
    private fun dp(v:Int)=(v*resources.displayMetrics.density).toInt()
    private fun label(text:String,size:Int=16,color:Int=Color.rgb(34,61,79))=TextView(this).apply{this.text=text;textSize=size.toFloat();setTextColor(color);setPadding(0,dp(4),0,dp(4));gravity=Gravity.CENTER}
    private fun background(color:Int,radius:Int=20)=GradientDrawable().apply{setColor(color);cornerRadius=dp(radius).toFloat()}
    private fun button(text:String,action:()->Unit)=Button(this).apply{this.text=text;isAllCaps=false;textSize=15f;typeface=Typeface.DEFAULT_BOLD;setTextColor(Color.WHITE);background=GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,intArrayOf(Color.rgb(92,167,225),Color.rgb(38,85,159))).apply{cornerRadius=dp(9).toFloat();setStroke(dp(2),Color.WHITE)};minimumHeight=dp(46);setPadding(dp(12),dp(3),dp(12),dp(3));setOnClickListener{sound.effect("click");action()}}
    private fun addButton(text:String,enabled:Boolean=true,action:()->Unit){val b=button(text,action);b.isEnabled=enabled;b.alpha=if(enabled)1f else .5f;panel?.addView(b,LinearLayout.LayoutParams(-1,dp(48)).apply{topMargin=dp(9)})}
    private fun card(title:String,subtitle:String){panel?.let{root.removeView(it)};panel=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(25),dp(22),dp(25),dp(24));background=background(Color.argb(244,255,247,226),26);elevation=dp(12).toFloat()};val p=FrameLayout.LayoutParams(min(resources.displayMetrics.widthPixels-dp(40),dp(360)),-2,Gravity.CENTER);root.addView(panel,p);panel!!.addView(label(title,32).apply{typeface=Typeface.create("sans-serif-black",Typeface.BOLD)});panel!!.addView(label(subtitle,14));}
    private fun startRun(){synchronized(engine){settle();engine.boards=save.boards;engine.start()};sound.start();screen="";syncUI(true)}
    private fun settle(){if(!engine.settled&&engine.mode!=Mode.MENU&&engine.distance>0){save.wallet+=engine.coins;save.totalCoins+=engine.coins;save.totalDistance+=engine.distance;save.runs++;save.best=max(save.best,engine.score);save.boards=engine.boards;engine.settled=true;save.store()}}
    private fun syncUI(force:Boolean=false){synchronized(engine){val m=engine.mode;if(System.currentTimeMillis()-lastLog>2000){lastLog=System.currentTimeMillis();android.util.Log.i("RailRush", "mode=$m d=${engine.distance.toInt()} x=${engine.x} y=${engine.y} coins=${engine.coins} score=${engine.score} entities=${engine.entities.size} powers=${engine.powers}")};val active=m==Mode.RUNNING||m==Mode.STARTING||m==Mode.COLLISION;hud.visibility=if(active)View.VISIBLE else View.GONE;boardButton.visibility=if(m==Mode.RUNNING)View.VISIBLE else View.GONE;boardButton.text=if(engine.powers.getValue("board")>0)"BOARD ACTIVE" else "BOARD · ${engine.boards}";stats.text="${if(engine.powers.getValue("multiplier")>0)"×2" else "×1"} ⭐ ${engine.score.toString().padStart(6,'0')}\n${engine.coins} 🟡";powers.text="";meters.visibility=if(active)View.VISIBLE else View.GONE;meters.update(engine.powers)
        if(m==Mode.STARTING)powers.text="GET READY  ·  ${ceil(engine.stageTime).toInt()}"
        if(force||m!=lastMode){lastMode=m;if(active){panel?.let{root.removeView(it)};panel=null;screen=""}else when(m){Mode.MENU->showMenu();Mode.PAUSED->showPause();Mode.RESULTS->{settle();sound.pause();showResults()};else->{}}}
    }}
    private fun showMenu(){screen="menu";panel?.let{root.removeView(it)};panel=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(18),dp(28),dp(18),dp(10));gravity=Gravity.CENTER_HORIZONTAL};root.addView(panel,FrameLayout.LayoutParams(-1,-1));panel!!.addView(View(this),LinearLayout.LayoutParams(1,0,1f));val play=button("Tap to Play"){startRun()}.apply{textSize=28f;typeface=Typeface.create("sans-serif-black",Typeface.BOLD_ITALIC)};panel!!.addView(play,LinearLayout.LayoutParams(dp(246),dp(58)));panel!!.addView(label("Best ${save.best}  ·  ◉ ${save.wallet}",14,Color.WHITE).apply{setShadowLayer(2f,0f,1f,Color.BLACK)});val row=LinearLayout(this);for((text,action)in listOf<Pair<String,()->Unit>>("Locker" to {showShop()},"Missions" to {showMissions()},"⚙" to {showSettings()})){row.addView(button(text,action),LinearLayout.LayoutParams(0,dp(42),1f).apply{setMargins(dp(4),dp(3),dp(4),0)})};panel!!.addView(row,LinearLayout.LayoutParams(-1,-2))}
    private fun showPause(){screen="pause";card("PAUSED","Continue when you are ready.");addButton("Continue run"){engine.resume();sound.start();syncUI(true)};addButton("Restart"){startRun()};addButton("Sound & controls"){showSettings()};addButton("Save & return home"){settle();engine.menu();syncUI(true)}}
    private fun showResults(){screen="results";card("NICE RUN!","${engine.distance.toInt()} metres on the tracks");panel!!.addView(label("${engine.score}",46).apply{typeface=Typeface.DEFAULT_BOLD});panel!!.addView(label("◉ +${engine.coins} earned   ·   Best ${save.best}",16));addButton("Run again  →"){startRun()};addButton("Home"){engine.menu();syncUI(true)}}
    private fun showShop(){screen="shop";card("THE LOCKER","◉ ${save.wallet} earned coins  ·  ${save.boards} boards");for((id,cost) in listOf("coral" to 0,"mint" to 120,"violet" to 240)){val owned=id in save.unlocked;addButton("${when(id){"coral"->"Jake";"mint"->"Outfit 1";else->"Outfit 2"}}  ·  ${if(id==save.skin)"Selected" else if(owned)"Wear" else "◉ $cost"}",owned||save.wallet>=cost){if(!owned){save.wallet-=cost;save.unlocked.add(id)};save.skin=id;renderer.skin=id;save.store();showShop()}};addButton("3 boards  ·  ◉ 30",save.wallet>=30){save.wallet-=30;save.boards+=3;engine.boards=save.boards;save.store();showShop()};addButton("Back"){showMenu()}}
    private fun showMissions(){screen="missions";card("MISSIONS","Lifetime missions  ·  claim each reward once");val rows=listOf(Triple("coins25",min(save.totalCoins,25).toString()+" / 25 coins",save.totalCoins>=25),Triple("distance1000","${min(save.totalDistance.toInt(),1000)} / 1,000 metres",save.totalDistance>=1000),Triple("runs3","${min(save.runs,3)} / 3 runs",save.runs>=3));for((i,row)in rows.withIndex()){val reward=listOf(40,60,30)[i];addButton("${row.second}  ·  ${if(row.first in save.claimed)"Claimed" else "+$reward ◉"}",row.third&&row.first !in save.claimed){save.claimed.add(row.first);save.wallet+=reward;save.store();showMissions()}};addButton("Back"){showMenu()}}
    private fun showSettings(){val paused=engine.mode==Mode.PAUSED;screen="settings";card("YOUR RHYTHM","Music & sound effects");addButton(if(save.muted)"Sound: muted" else "Sound: on"){save.muted=!save.muted;save.store();sound.volume();showSettings()};panel!!.addView(label("Volume ${(save.volume*100).toInt()}%",14));panel!!.addView(SeekBar(this).apply{max=100;progress=(save.volume*100).toInt();setOnSeekBarChangeListener(object:SeekBar.OnSeekBarChangeListener{override fun onProgressChanged(s:SeekBar?,p:Int,user:Boolean){save.volume=p/100.0;sound.volume();save.store()};override fun onStartTrackingTouch(s:SeekBar?){};override fun onStopTrackingTouch(s:SeekBar?){} })});panel!!.addView(label("Swipe left/right to switch tracks.\nSwipe up to jump; down to roll.\nDouble-tap or BOARD to protect a crash.\nPickups: magnet, jetpack, boots, ×2, board.",14));addButton("Back"){if(paused)showPause()else showMenu()}}
    override fun onPause(){super.onPause();if(::engine.isInitialized){synchronized(engine){engine.pause()};sound.pause();surface.onPause();save.store()}}
    override fun onResume(){super.onResume();if(::surface.isInitialized){surface.onResume();syncUI(true)}}
    override fun onWindowFocusChanged(focus:Boolean){super.onWindowFocusChanged(focus);if(!focus&&::engine.isInitialized){synchronized(engine){engine.pause()};sound.pause();syncUI(true)}}
    override fun onDestroy(){destroyed=true;handler.removeCallbacksAndMessages(null);if(::sound.isInitialized)sound.release();super.onDestroy()}
    @Deprecated("Native back pause") override fun onBackPressed(){if(engine.mode==Mode.RUNNING||engine.mode==Mode.STARTING){engine.pause();sound.pause();syncUI(true)}else if(engine.mode==Mode.PAUSED)showPause()else if(screen!="menu")showMenu()else super.onBackPressed()}
    override fun onKeyDown(keyCode:Int,event:KeyEvent?):Boolean {synchronized(engine){when(keyCode){KeyEvent.KEYCODE_DPAD_LEFT,KeyEvent.KEYCODE_A->engine.move(-1);KeyEvent.KEYCODE_DPAD_RIGHT,KeyEvent.KEYCODE_D->engine.move(1);KeyEvent.KEYCODE_DPAD_UP,KeyEvent.KEYCODE_W,KeyEvent.KEYCODE_SPACE->engine.jump();KeyEvent.KEYCODE_DPAD_DOWN,KeyEvent.KEYCODE_S->engine.down();KeyEvent.KEYCODE_B->engine.board();KeyEvent.KEYCODE_P,KeyEvent.KEYCODE_ESCAPE->{engine.pause();sound.pause();syncUI(true)};else->return super.onKeyDown(keyCode,event)}};return true}
    inner class Save {private val prefs=getSharedPreferences("railrush.v1",MODE_PRIVATE);var best=0;var wallet=0;var totalCoins=0;var totalDistance=0.0;var runs=0;var boards=3;var skin="coral";val unlocked=mutableSetOf("coral");val claimed=mutableSetOf<String>();var muted=false;var volume=.55
        init{try{val s=JSONObject(prefs.getString("save","{}")!!);best=max(0,s.optInt("best"));wallet=max(0,s.optInt("wallet"));totalCoins=max(0,s.optInt("totalCoins"));totalDistance=max(0.0,s.optDouble("totalDistance",0.0));runs=max(0,s.optInt("runs"));boards=max(0,s.optInt("boards",3));skin=s.optString("selectedSkin","coral");val u=s.optJSONArray("unlocked");if(u!=null)for(i in 0 until u.length())unlocked.add(u.getString(i));if(skin !in unlocked)skin="coral";val c=s.optJSONArray("claimed");if(c!=null)for(i in 0 until c.length())claimed.add(c.getString(i));muted=s.optBoolean("muted");volume=s.optDouble("volume",.55).coerceIn(0.0,1.0)}catch(_:Exception){}}
        fun store(){val j=JSONObject().put("schemaVersion",1).put("best",best).put("wallet",wallet).put("totalCoins",totalCoins).put("totalDistance",totalDistance).put("runs",runs).put("boards",boards).put("selectedSkin",skin).put("unlocked",JSONArray(unlocked.toList())).put("claimed",JSONArray(claimed.toList())).put("muted",muted).put("volume",volume);prefs.edit().putString("save",j.toString()).apply()}
    }
    inner class GameAudio {private val manager=getSystemService(AUDIO_SERVICE) as AudioManager;private val pool=SoundPool.Builder().setMaxStreams(8).setAudioAttributes(AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_GAME).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build()).build();private val ids=mutableMapOf<String,Int>();private var music:MediaPlayer?=null;private var hasFocus=false
        private val request=AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_GAME).build()).setOnAudioFocusChangeListener{change->if(change<0){handler.post{synchronized(engine){engine.pause()};pause();syncUI(true)}}}.build()
        init{for(n in listOf("coin","jump","roll","power","crash","click"))try{assets.openFd("recovered/audio/${when(n){"jump","roll"->"swish";"crash"->"stumble";else->n}}.wav").use{ids[n]=pool.load(it,1)}}catch(_:Exception){};try{assets.openFd("recovered/audio/music.wav").use{fd->music=MediaPlayer().apply{setDataSource(fd.fileDescriptor,fd.startOffset,fd.length);isLooping=true;prepare()}}}catch(_:Exception){};volume()}
        fun start(){hasFocus=manager.requestAudioFocus(request)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED;volume();if(hasFocus&&!save.muted)music?.start()}
        fun pause(){music?.pause();if(hasFocus){manager.abandonAudioFocusRequest(request);hasFocus=false}}
        fun volume(){val v=if(save.muted)0f else save.volume.toFloat();music?.setVolume(v,v);if(save.muted)music?.pause()else if(hasFocus&&(engine.mode==Mode.RUNNING||engine.mode==Mode.STARTING))music?.start()}
        fun effect(name:String){if(save.muted)return;val n=if(name=="shield")"power" else name;ids[n]?.let{pool.play(it,save.volume.toFloat(),save.volume.toFloat(),1,0,1f)}}
        fun release(){pause();music?.release();pool.release()}
    }
}
